diff --git a/pandas/core/arrays/string_.py b/pandas/core/arrays/string_.py
index 9b26db07fc..952fd3a19d 100644
--- a/pandas/core/arrays/string_.py
+++ b/pandas/core/arrays/string_.py
@@ -414,14 +414,14 @@ class StringArray(BaseStringArray, PandasArray):
             if isna(value):
                 value = libmissing.NA
             elif not isinstance(value, str):
-                raise ValueError(
+                raise TypeError(
                     f"Cannot set non-string value '{value}' into a StringArray."
                 )
         else:
             if not is_array_like(value):
                 value = np.asarray(value, dtype=object)
             if len(value) and not lib.is_string_array(value, skipna=True):
-                raise ValueError("Must provide strings.")
+                raise TypeError("Must provide strings.")

             value[isna(value)] = libmissing.NA

diff --git a/pandas/core/arrays/string_arrow.py b/pandas/core/arrays/string_arrow.py
index 4aebe61412..92385b64f5 100644
--- a/pandas/core/arrays/string_arrow.py
+++ b/pandas/core/arrays/string_arrow.py
@@ -163,13 +163,13 @@ class ArrowStringArray(ArrowExtensionArray, BaseStringArray, ObjectStringArrayMi
             if isna(value):
                 value = None
             elif not isinstance(value, str):
-                raise ValueError("Scalar must be NA or str")
+                raise TypeError("Scalar must be NA or str")
         else:
             value = np.array(value, dtype=object, copy=True)
             value[isna(value)] = None
             for v in value:
                 if not (v is None or isinstance(v, str)):
-                    raise ValueError("Scalar must be NA or str")
+                    raise TypeError("Scalar must be NA or str")
         return super()._maybe_convert_setitem_value(value)

     def isin(self, values) -> npt.NDArray[np.bool_]:
